head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf30360";
scwin.pathname = undefined;
scwin.qry = undefined;
scwin.usr_id = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — today, cntlength, param.CONFROOM, result

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_88", fn: function(){ return (((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())+1) % 7 === 0); } }, { id: "c_when_90", fn: function(){ return (((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())+1) % 7 === 1); } }, { id: "c_otherwise_92", fn: function(){ return (!((((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())+1) % 7 === 0) || (((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())+1) % 7 === 1))); } }, { id: "if_index", fn: function(){ return ((dma_rowInfostatus.get("index") ?? (() => { throw new Error("unresolved:" + "rowInfostatus.index"); })()) === 0); } }, { id: "txt_text104", fn: function(){ return ((dlt_rowCalendarValue.getCellData(0, "admDeadlineDd") ?? (() => { throw new Error("unresolved:" + "rowInfo.admDeadlineDd"); })()) > (dma_pageContext.get("today") ?? "")); } }, { id: "btn_cancel", fn: function(){ return ((dlt_rowCalendarValue.getCellData(0, "admDeadlineDd") ?? (() => { throw new Error("unresolved:" + "rowInfo.admDeadlineDd"); })()) > (dma_pageContext.get("today") ?? "")); } }, { id: "if_irConfroomTpNm", fn: function(){ return (!(String(((dlt_rowCalendarValue.getCellData(0, "irConfroomTpNm") ?? (() => { throw new Error("unresolved:" + "rowInfo.irConfroomTpNm"); })())) === null ? '' : ((dlt_rowCalendarValue.getCellData(0, "irConfroomTpNm") ?? (() => { throw new Error("unresolved:" + "rowInfo.irConfroomTpNm"); })()))).length === 0)); } }, { id: "if_irConfroomTpNm", fn: function(){ return ((dma_pageContext.get("cntlength") ?? "") > 1); } }, { id: "c_otherwise_107", fn: function(){ return (!(((dma_pageContext.get("cntlength") ?? "") > 1))); } }, { id: "c_otherwise_110", fn: function(){ return (!((((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())+1) % 7 === 0 || ((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())+1) % 7 === 1 || (dlt_rowCalendarValue.getCellData(0, "mktHoldyYn") ?? (() => { throw new Error("unresolved:" + "rowInfo.mktHoldyYn"); })()) === 'Y'|| (dlt_rowCalendarValue.getCellData(0, "admDeadlineDd") ?? (() => { throw new Error("unresolved:" + "rowInfo.admDeadlineDd"); })()) <= (dma_pageContext.get("today") ?? "")))); } }, { id: "c_otherwise_113", fn: function(){ return (!(((dma_pageContext.get("CONFROOM") ?? "") === '' || (String(((dma_pageContext.get("CONFROOM") ?? "")) === null ? '' : ((dma_pageContext.get("CONFROOM") ?? ""))).length === 0)))); } }, { id: "if_admDeadlineDd", fn: function(){ return (!(String(((dlt_rowCalendarValue.getCellData(0, "admDeadlineDd") ?? (() => { throw new Error("unresolved:" + "rowInfo.admDeadlineDd"); })())) === null ? '' : ((dlt_rowCalendarValue.getCellData(0, "admDeadlineDd") ?? (() => { throw new Error("unresolved:" + "rowInfo.admDeadlineDd"); })()))).length === 0)); } }, { id: "c_otherwise_123", fn: function(){ return (!(((dma_pageContext.get("CONFROOM") ?? "") === ''|| (String(((dma_pageContext.get("CONFROOM") ?? "")) === null ? '' : ((dma_pageContext.get("CONFROOM") ?? ""))).length === 0)))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_81", entity: "dlt_rowCalendarValue", countIds: [], cells: [{ childId: "__rc0", fn: function (v, i) { return String(String(v("admDeadlineDd")).substring(6, 8)); } }, { childId: "__rc1", fn: function (v, i) { return String(String(v("admDeadlineDd")).substring(6, 8)); } }, { childId: "__rc2", fn: function (v, i) { return String(String(v("admDeadlineDd")).substring(6, 8)); } }, { childId: "__rc3", fn: function (v, i) { return String(v("irConfroomTpNm")); } }, { childId: "ipt_chck", fn: function (v, i) { return String(v("admDeadlineDd")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.pathname =location.pathname; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30360' }); }

try { scwin.qry =location.search; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30360' }); }

try { scwin.usr_id =$c.session.getUserInfo("id"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30360' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        scwin.init_fillGen();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf30360.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf30360.btn_Search_onclick' }); }
};

/**
 * @method
 * @name btn_cancel_onclick
 * @description 「취소」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_cancel_onclick = async function(e){
    try {
        await scwin.cancel('' + dlt_rowCalendarValue.getCellData(0, "admDeadlineDd") + '','' + dlt_rowCalendarValue.getCellData(0, "irConfroomTpNm") + '','' + dlt_rowCalendarValue.getCellData(0, "irConfroomTpCd") + '','' + dlt_rowCalendarValue.getCellData(0, "byddSeq") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf30360.btn_cancel_onclick' }); }
};

/**
 * @method
 * @name btn_input_onclick
 * @description btn_input 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_input_onclick = async function(e){
    try {
        await scwin.input()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf30360.btn_input_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/IRMgtKosdaq.do",
        ref: "dma_SearchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_cancel
 * @description cancel 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_cancel = async function () {
    const sbmOptions = {
        id: "tx_fn_cancel",
        method: "post",
        action: "/IRMgtKosdaq.do",
        ref: "dma_cancelReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_check
 * @description check 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_check = async function () {
    const sbmOptions = {
        id: "tx_fn_check",
        method: "post",
        action: "/IRMgtKosdaq.do",
        ref: "dma_checkReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/IRMgtKosdaq.do",
        ref: "dma_loadListReq",
        target: "dlt_cmbConfRoom=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    if (($c.util.getComponent('rd_MKT_ID').getValue() === null ? '' : String($c.util.getComponent('rd_MKT_ID').getValue())) === '') {
        await $c.win.alert("[시장구분]을 선택하세요.");
        $c.util.getComponent("rd_MKT_ID").focus();
        return;
    }
    if ($c.util.getComponent('slc_YYYY').getValue() === "") {
        await $c.win.alert("[년도]을 선택하세요.");
        $c.util.getComponent("slc_YYYY").focus();
        return;
    }
    if ($c.util.getComponent('slc_MM').getValue() === "") {
        await $c.win.alert("[월]을 선택하세요.");
        $c.util.getComponent("slc_MM").focus();
        return;
    }
    $c.util.getComponent('dma_SearchReq').set('method', "listMonthlyIRSprtInfoSchedule");
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name cancel
 * @description cancel 처리
 * @param {*} selectDate selectDate
 * @param {*} confroomName confroomName
 * @param {String} confroomCd confroomCd
 * @param {*} seq seq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cancel = async function (selectDate, confroomName, confroomCd, seq) {
    if (await $c.win.confirm(selectDate + " " + confroomName + "을 취소 시겠습니까?")) {
        $c.util.getComponent('dma_SearchReq').set('selectDate', selectDate);
        $c.util.getComponent('dma_SearchReq').set('confroomCd', confroomCd);
        $c.util.getComponent('dma_SearchReq').set('seq', seq);
        $c.util.getComponent('dma_SearchReq').set('usrId', scwin.usr_id);
        $c.util.getComponent('dma_SearchReq').set('sType', "D");
        $c.util.getComponent('dma_SearchReq').set('method', "cancelIRSprtInfoSchedule");
        await scwin.tx_fn_cancel();
    }
};

/**
 * @method
 * @name input
 * @description input 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.input = async function () {
    if (IRMgtKosdaqForm.CONFROOM.value === "") {
        await $c.win.alert("장소를 선택후 입력해주십시오");
        $c.util.getComponent("slc_CONFROOM").focus();
        return;
    }
    await scwin.check();
};

/**
 * @method
 * @name check
 * @description check 처리
 * @param {String} confroomCd confroomCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.check = async function (confroomCd) {
    const checkList = document.getElementsByName("ipt_chck");
    const arrList = [];
    let cnt = 0;
    for (let i = checkList.length - 1; 0 <= i; i--) {
        if (checkList[i].checked) {
            arrList[cnt] = checkList[i].value;
            cnt++;
        }
    }
    $c.util.getComponent('ipt_checktnList').setValue(arrList);
    if (arrList.length !== 0) {
        if (await $c.win.confirm("저장 하시겠습니까?")) {
            $c.util.getComponent('dma_SearchReq').set('usrId', scwin.usr_id);
            $c.util.getComponent('dma_SearchReq').set('confroomCd', "" + dma_pageContext.get("CONFROOM") + "");
            $c.util.getComponent('dma_SearchReq').set('sType', "I");
            $c.util.getComponent('dma_SearchReq').set('method', "inputIRSprtInfoSchedule");
            await scwin.tx_fn_check();
        }
    } else {
        await $c.win.alert("선택한 일자가 없습니다.");
        return;
    }
};

/**
 * @method
 * @name GetQueryString
 * @description Get Query String 처리
 * @param {*} q_name q_name
 * @returns {void}
 * @hidden N
 */
scwin.GetQueryString = function (q_name) {
    m_url = location.search;
    m_url = m_url.slice(1);
    const v_result = {  };
    v_querys = m_url.split("&");
    for (let i = 0; i < v_querys.length; i++) {
        v_query = v_querys[i].split("=");
        v_result[v_query[0]] = v_query[1];
    }
    if (v_result[q_name] !== null) {
        return v_result[q_name];
    } else {
        return false;
    }
};

/**
 * @method
 * @name lpad
 * @description lpad 처리
 * @param {*} src src
 * @param {*} len len
 * @param {String} padStr padStr
 * @returns {void}
 * @hidden N
 */
scwin.lpad = function (src, len, padStr) {
    let retStr = "";
    const padCnt = Number(len) - String(src).length;
    for (let i = 0; i < padCnt; i++) {
        retStr += String(padStr);
    }
    return retStr + src;
};

/**
 * @method
 * @name setDefault
 * @description set Default 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setDefault = async function () {
    if (scwin.GetQueryString("YYYY") === false) {
        let checked = "2";
        if (checked === "6") {
            checked = "3";
        }
        $c.util.getComponent('rd_MKT_ID')[checked - 1].checked = true;
        const date = new Date();
        const sYYYY = date.getYear();
        const sMM = parseInt(date.getMonth(), 10) + 1;
        $c.util.getComponent("slc_YYYY").setValue(sYYYY);
        $c.util.getComponent("slc_MM").setValue(scwin.lpad(sMM, 2, "0"));
        await scwin.search();
    }
    if (scwin.GetQueryString("sType") === "D" || scwin.GetQueryString("sType") === "I") {
        let sTypeStr;
        let sResultStr;
        if (scwin.GetQueryString("sType") === "D") {
            sTypeStr = "취소에";
        } else {
            sTypeStr = "저장에";
        }
        if ((String(((dma_pageContext.get("result") ?? "")) === null ? '' : ((dma_pageContext.get("result") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("result") ?? "")) === null ? '' : ((dma_pageContext.get("result") ?? "")))) > 0) {
            sResultStr = "성공 하였습니다.";
        } else {
            sResultStr = "실패 하였습니다.";
        }
        await $c.win.alert(sTypeStr + " " + sResultStr);
        $c.util.getComponent('dma_SearchReq').set('sType', "S");
        await scwin.search();
    }
};

/**
 * @method
 * @name insertOption
 * @description insert Option 처리
 * @param {*} selectObject selectObject
 * @param {*} value value
 * @param {*} text text
 * @returns {void}
 * @hidden N
 */
scwin.insertOption = function (selectObject, value, text) {
    if (selectObject === null) {
        return false;
    }
    for (i = 0; i < selectObject.length; i++) {
        if (selectObject.options[i].value === value) {
            return;
        }
    }
    const e1 = document.createElement("OPTION");
    e1.text = text;
    e1.value = value;
    selectObject.options.add(e1);
};
